static string readKey() {
    string out;
    p++;
    while (doc[p] != '"') {
        char c = doc[p++];
        if (c != '\\') { out += c; continue; }
        char e = doc[p++];
        if (e == 'u') {
            int v = stoi(doc.substr(p, 4), nullptr, 16);
