public class Main {
    // Walks the JSON text directly: find each key in the current object, then print the raw value.
    static byte[] doc;
    static int len, p;

    static boolean isWs(byte c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\r';
    }

    static void ws() {
        while (p < len && isWs(doc[p])) p++;
    }

    static void skipString() {
        p++;
        while (doc[p] != '"') {
            if (doc[p] == '\\') p++;
            p++;
        }
        p++;
    }

    // Decodes a key; any non-ASCII escape or byte becomes 'ÿ' since valid path keys are ASCII.
    static String readKey() {
        StringBuilder out = new StringBuilder();
        p++;
        while (doc[p] != '"') {
            byte c = doc[p++];
            if (c != '\\') {
                out.append(c >= 0 ? (char) c : 'ÿ');
                continue;
            }
            byte e = doc[p++];
            if (e == 'u') {
                int v = Integer.parseInt(new String(doc, p, 4), 16);
                p += 4;
                out.append(v < 0x80 ? (char) v : 'ÿ');
            } else {
                out.append("\"\\/\b\f\n\r\t".charAt("\"\\/bfnrt".indexOf(e)));
            }
        }
        p++;
        return out.toString();
    }

    static void skipValue() {
        ws();
        byte c = doc[p];
        if (c == '"') {
            skipString();
            return;
        }
        if (c == '{' || c == '[') {
            int depth = 0;
            while (true) {
                byte d = doc[p];
                if (d == '"') {
                    skipString();
                    continue;
                }
                if (d == '{' || d == '[') depth++;
                else if (d == '}' || d == ']') {
                    if (--depth == 0) {
                        p++;
                        return;
                    }
                }
                p++;
            }
        }
        while (p < len && doc[p] != ',' && doc[p] != '}' && doc[p] != ']' && !isWs(doc[p])) p++;
    }

    public static void main(String[] args) throws IOException {
        byte[] raw = System.in.readAllBytes();
        int nl = 0;
        while (raw[nl] != '\n') nl++;
        doc = raw;
        len = nl;
        int end = raw.length;
        while (end > nl + 1 && (raw[end - 1] == '\n' || raw[end - 1] == '\r')) end--;
        String path = new String(raw, nl + 1, end - nl - 1, "UTF-8");
        PrintStream out = new PrintStream(new FileOutputStream(FileDescriptor.out), false);
        p = 0;
        for (String key : path.split("\\.", -1)) {
            ws();
            if (doc[p] != '{') {
                out.print("null\n");
                out.flush();
                return;
            }
            p++;
            boolean found = false;
            while (true) {
                ws();
                if (doc[p] == '}') break;
                String k = readKey();
                ws();
                p++; // ':'
                ws();
                if (k.equals(key)) {
                    found = true;
                    break;
                }
                skipValue();
                ws();
                if (doc[p] == ',') p++;
            }
            if (!found) {
                out.print("null\n");
                out.flush();
                return;
            }
        }
        ws();
        int start = p;
        skipValue();
        out.write(doc, start, p - start);
        out.write('\n');
        out.flush();
    }
