import (
	"bufio"
	"io"
	"os"
	"strconv"
	"strings"
)

// Walks the JSON text directly: find each key in the current object, then print the raw value.
var doc []byte
var p int

func isWs(c byte) bool { return c == ' ' || c == '\t' || c == '\n' || c == '\r' }

func ws() {
	for p < len(doc) && isWs(doc[p]) {
		p++
	}
}

func skipString() {
	p++
	for doc[p] != '"' {
		if doc[p] == '\\' {
			p++
		}
		p++
	}
	p++
}

// readKey decodes a key; non-ASCII escapes become 0xFF since valid path keys are ASCII.
func readKey() string {
	var out []byte
	p++
	for doc[p] != '"' {
		c := doc[p]
		p++
		if c != '\\' {
			out = append(out, c)
			continue
		}
		e := doc[p]
		p++
		if e == 'u' {
			v, _ := strconv.ParseUint(string(doc[p:p+4]), 16, 32)
			p += 4
			if v < 0x80 {
				out = append(out, byte(v))
			} else {
				out = append(out, 0xFF)
			}
		} else {
			out = append(out, "\"\\/\b\f\n\r\t"[strings.IndexByte("\"\\/bfnrt", e)])
		}
	}
	p++
	return string(out)
}

func skipValue() {
	ws()
	c := doc[p]
	if c == '"' {
		skipString()
		return
	}
	if c == '{' || c == '[' {
		depth := 0
		for {
			d := doc[p]
			if d == '"' {
				skipString()
				continue
			}
			if d == '{' || d == '[' {
				depth++
			} else if d == '}' || d == ']' {
				depth--
				if depth == 0 {
					p++
					return
				}
			}
			p++
		}
	}
	for p < len(doc) && doc[p] != ',' && doc[p] != '}' && doc[p] != ']' && !isWs(doc[p]) {
		p++
	}
}

func main() {
	raw, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	nl := strings.IndexByte(string(raw), '\n')
	doc = raw[:nl]
	path := strings.TrimRight(string(raw[nl+1:]), "\r\n")
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for _, key := range strings.Split(path, ".") {
		ws()
		if doc[p] != '{' {
			w.WriteString("null\n")
			return
		}
		p++
		found := false
		for {
			ws()
			if doc[p] == '}' {
				break
			}
			k := readKey()
			ws()
			p++ // ':'
			ws()
			if k == key {
				found = true
				break
			}
			skipValue()
			ws()
			if doc[p] == ',' {
				p++
			}
		}
		if !found {
			w.WriteString("null\n")
			return
		}
	}
	ws()
	start := p
	skipValue()
	w.Write(doc[start:p])
	w.WriteByte('\n')
}
